async function replayTrace(){
  if(running||!currentRun)return;
  if(replaying){replayToken++;replaying=false;renderTraceStrip();return;}
  const token=++replayToken;replaying=true;
  for(let i=0;i<currentRun.invocations.length;i++){if(token!==replayToken)return;scrubTrace(i);await new Promise(resolve=>setTimeout(resolve,700));}
  if(token===replayToken){replaying=false;renderTraceStrip();toast('Recorded trace replayed. No model or tool was called.');}
}
function compareRuns(firstId,secondId){
  if(history.length<2){toast('Complete two runs to compare their configurations and outcomes.');return;}
  const first=history.find(r=>r.id===firstId)||history[1],second=history.find(r=>r.id===secondId)||history[0];
  const retry=r=>r.graph.edges.find(e=>e.id==='e5').maxAttempts;
  const threshold=r=>r.graph.nodes.find(n=>n.id==='council').threshold;
  const fields=[['Graph revision',`v${first.version}`,`v${second.version}`],['Outcome',first.status,second.status],['Max revisions',retry(first),retry(second)],['Evidence threshold',threshold(first),threshold(second)],['Invocations',first.invocations.length,second.invocations.length],['Simulated elapsed',`${(first.elapsed/1000).toFixed(1)}s`,`${(second.elapsed/1000).toFixed(1)}s`]];
  const changes=second.graph.nodes.filter(n=>JSON.stringify(n)!==JSON.stringify(first.graph.nodes.find(o=>o.id===n.id))).map(n=>n.name);
  const edgeChanges=second.graph.edges.filter(n=>JSON.stringify(n)!==JSON.stringify(first.graph.edges.find(o=>o.id===n.id))).map(n=>n.type+' connection');
  const sameInput=first.input===second.input;
  modal(`<div class="section-eyebrow">RUN COMPARISON / RECORDED EVIDENCE</div><h2>What changed.<br>What happened next.</h2><p>${sameInput?'Same sample input. Compare the configuration and observed fixture outcome.':'Different sample inputs. This comparison cannot isolate the effect of a configuration change.'}</p><div class="compare-table"><div class="compare-line compare-heading"><span>CONTRACT / RESULT</span><span>BEFORE <b>${esc(first.id)}</b></span><span>AFTER <b>${esc(second.id)}</b></span></div>${fields.map(f=>`<div class="compare-line ${String(f[1])!==String(f[2])?'changed':''}"><span>${f[0]}</span><span>${esc(f[1])}</span><span>${esc(f[2])}${String(f[1])!==String(f[2])?' <i>changed</i>':''}</span></div>`).join('')}</div><div class="callout">${changes.length||edgeChanges.length?`Changed definitions: ${esc([...changes,...edgeChanges].join(', '))}.`:'No workflow definition changed between these runs.'} ${first.scenario!==second.scenario?'The selected fixture scenario also changed.':''} Timing is from the simulator and is not a model-performance benchmark.</div><div class="compare-outputs"><div><div class="field-label">BEFORE · ${esc(first.status)}</div><p>${esc(first.response)}</p></div><div><div class="field-label">AFTER · ${esc(second.status)}</div><p>${esc(second.response)}</p></div></div><div class="modal-actions"><button class="button" data-compare-inspect="${first.id}">Inspect before</button><button class="button primary" data-compare-inspect="${second.id}">Inspect after ${icon('arrow')}</button></div>`,true);
}
