  const actions=[['debug-tour','Guided failure & repair','Inspect and fix a controlled failure'],['hidden-nodes','Hidden nodes','UI, database, auth and documentation'],['compare','Compare recent runs','Configuration differences and outcomes'],['export','Export graph','Download this versioned configuration'],['new','New system','Describe, review, configure']].filter(a=>a.slice(1).join(' ').toLowerCase().includes(q));
