function startDebugMission(){
  if(running){toast('Stop the current run before starting the guided repair.');return;}
  modal(`<div class="section-eyebrow">GUIDED REPAIR / 90 SECOND EXPLORATION</div><h2>Break it. Understand it.<br>Make one precise fix.</h2><p>The first research draft has an unsupported claim. We’ll set the revision limit to zero so the evaluator catches the problem and the run stops.</p><div class="plan-step"><span>01</span><div><h3>Watch the failure</h3><p>See the exact evidence verdict and the contract that prevents recovery.</p></div></div><div class="plan-step"><span>02</span><div><h3>Edit one connection</h3><p>Allow one revision on the feedback edge, then rerun the same sample.</p></div></div><div class="plan-step"><span>03</span><div><h3>Compare the result</h3><p>Both runs keep their original configuration and individual invocation outputs.</p></div></div><div class="callout">This sets the evaluator threshold to 0.85 and saves a new draft revision with zero retries. It uses local fixtures. No prompt or implementation code is executed.</div><div class="modal-actions"><span>Controlled failure · no external side effects</span><button class="button primary" data-action="begin-debug">Start guided repair ${icon('arrow')}</button></div>`);
}
function handleDebugOutcome(){
  if(!debugMission)return;
  if(currentRun.status==='cancelled'){debugMission=null;return;}
  if(debugMission.stage==='failure'&&currentRun.status==='failed'){
    debugMission.before=currentRun.id;debugMission.stage='repair';
    modal(`<div class="section-eyebrow">FAILURE FOUND / NO REVISION ALLOWED</div><h2>The reviewer did its job.<br>The contract stopped recovery.</h2><p>The initial evidence score was <strong>0.62</strong>, below the <strong>0.85</strong> requirement. Feedback identifies a missing source, but the feedback edge allows zero revisions.</p><div class="mini-graph">Evidence reviewer → Research agent\nCondition: revise\nMaximum revisions: 0\nResult: stopped with an unresolved claim</div><div class="callout">Change the feedback edge’s maximum revisions to 1. Apply the change, then run the same input again.</div><div class="modal-actions"><span>Your failed trace is preserved.</span><button class="button primary" data-action="inspect-fix">Inspect the feedback edge ${icon('arrow')}</button></div>`);
  }else if(debugMission.stage==='repair'&&currentRun.status==='complete'){const before=debugMission.before;debugMission=null;compareRuns(before,currentRun.id);}
}

function renderBlueprint(){
  const decisions=[['The graph is the executable contract','One versioned manifest defines components, allowed calls, input bindings, output schemas, conditions, budgets and failure routes. The UI and runtime read the same source.','Rejected: maintaining a diagram, generated code and live runtime as three independent sources of truth.'],['Roles describe purpose; types determine behavior','Keep Citadel, Army, Armory, Council and Court as optional vocabulary. Underneath: agent, function, tool, router, evaluator, policy and human approval. Add subgraphs as complexity grows.','Rejected: making every role an LLM, or forcing every request through a central King.'],['Connections must mean something precise','Separate delegates, calls, evaluates, routes and feedback. A delegate edge includes a child result. Data is explicitly mapped. Conditions, retry limits and failure behavior are visible.','Rejected: unlabeled arrows whose behavior is hidden inside long prompts.'],['A node definition is not a single execution','A reusable agent may execute three times in a run. Store every invocation with parent ID, input, output, version, timing and tool events; overlay these on the design graph.','Rejected: replacing a node’s first output with its latest output, or treating an observed trace as the complete design.'],['Policies execute; reviewers advise','Deterministic checks control permissions, schemas, destinations and budgets. Model-based critique returns a structured judgment with bounded retries. Buffer final output until release checks pass.','Rejected: treating “do not leak secrets” in a system prompt as an enforceable security boundary.']];
  $('#blueprint-page').innerHTML=`<article class="blueprint-layout"><div class="blueprint-hero"><div><div class="section-eyebrow">PRODUCT THESIS / PROPOSED DESIGN</div><h2>Build the system.<br>See why it behaves that way.</h2><p>A graph-first workbench for small AI teams building research, review and support workflows. The value is a shorter path from a failed answer to the specific contract that needs fixing.</p><div class="pill-row"><span class="mini-pill">Developer-led teams</span><span class="mini-pill">Inspectable contracts</span><span class="mini-pill">Human control</span></div></div><aside class="thesis"><div class="section-eyebrow">THE PRODUCT LOOP</div><div class="big">Edit → run → learn</div><p>Make a change, observe its effect, inspect the result, then compare against the previous version.</p><p><strong>Graph as interface. Contracts as the product.</strong></p></aside></div><div class="blueprint-columns"><section><div class="section-eyebrow">SIX DESIGN CALLS</div><h3>Control without scattered glue.</h3><div class="decision-row"><span>00</span><div><h4>One app graph. A focused workflow view.</h4><p>UI code, database connections, authentication wiring and Markdown live in a collapsed Hidden nodes section. Select an agent to reveal its dependencies. Supporting resources remain versioned, searchable and inspectable.</p><p class="reject">Rejected: putting every file on the execution canvas, or hiding infrastructure failures from the trace.</p></div></div>${decisions.map((d,i)=>`<div class="decision-row"><span>0${i+1}</span><div><h4>${d[0]}</h4><p>${d[1]}</p><p class="reject">${d[2]}</p></div></div>`).join('')}</section><section><div class="section-eyebrow">THE HARD CRITIQUE</div><h3>A graph alone is not the gap.</h3><div class="criticism"><h4>01 / The baseline already exists</h4><p>Langflow combines visual building, editable Python components and a playground. LangSmith Studio visualizes graph execution and state. Live animation is useful, but not a durable distinction. Win on diagnosing and repairing contract failures.</p></div><div class="criticism"><h4>02 / Complexity does not disappear</h4><p>Without explicit state, conditions and failure rules, users still debug code—plus a canvas. Collapse tools and policy detail by default; show only the level relevant to the current question.</p></div><div class="criticism"><h4>03 / Arbitrary code import is a separate product</h4><p>Static code cannot reveal every dynamic tool call. Traces show only paths that happened. Start with one supported framework, read-only discovery, source links and declared / inferred / observed confidence. Edits become reviewable patches later.</p></div><div class="criticism"><h4>04 / Reflection can add cost without truth</h4><p>A confident reviewer can still be wrong. Require cited evidence, deterministic tests where possible, a revision cap and regression examples. Prefer the smallest system that meets the quality bar.</p></div><div class="criticism"><h4>05 / Full control needs an escape hatch</h4><p>Allow custom code and subgraphs behind stable interfaces. Run code in isolated workers with restricted network and scoped secrets. These are runtime requirements; this prototype does not implement them.</p></div><div class="callout amber"><strong>Recommended validation:</strong> give five builders a real failed workflow. Proceed if four independently diagnose and repair it, three ask to reuse the product, and two will discuss a paid pilot. These are proposed thresholds, not market evidence.</div></section></div><div class="scope-strip"><section><h4>BUILD FIRST</h4><p>One runtime and provider. Versioned manifest. Prompt-to-plan-to-graph approval. Typed node and edge editors. Three fixture scenarios. Real invocation traces. Bounded feedback. Export and regression cases.</p></section><section><h4>DEFER DELIBERATELY</h4><p>Arbitrary repository round-trip editing. Multi-framework execution. Autonomous deployment. A marketplace. Large graph collaboration. A hosted code sandbox before the core editing loop proves useful.</p></section><section><h4>WHAT EXISTS IN THIS PROTOTYPE</h4><p>Editable graph and hidden resources, schema JSON checks, revision snapshots, bounded simulation, guided repair, trace replay, run comparison and per-invocation outputs. No live models, repository import, sandbox or production enforcement.</p><a href="product-critique.md" download>Download product critique ↗</a><br><a href="execution-model.md" download>Download execution model ↗</a></section></div><div class="source-links"><span class="subtle">COMPETITIVE REFERENCES</span><a href="https://docs.langflow.org/concepts-overview" target="_blank" rel="noreferrer">Langflow</a><a href="https://docs.langchain.com/langsmith/studio" target="_blank" rel="noreferrer">LangSmith Studio</a><a href="https://docs.dify.ai/en/cloud/use-dify/debug/step-run" target="_blank" rel="noreferrer">Dify</a><a href="https://langfuse.com/docs/observability/features/agent-graphs" target="_blank" rel="noreferrer">Langfuse agent graphs</a></div></article>`;
}

function modal(content,wide=false){$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="Workspace dialog"><button class="icon-button modal-close" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button>${content}</section></div>`;setTimeout(()=>$('.modal textarea,.modal input:not(:disabled),.modal button:not(.modal-close)')?.focus(),50);}
function closeModal(){$('#modal-root').innerHTML='';}
function newSystem(){replayToken++;replaying=false;if(running){toast('Finish or stop the current run before creating a system.');return;}newPlanStep=1;renderNewSystem();}
function renderNewSystem(){
  if(newPlanStep===1)modal(`<div class="section-eyebrow">NEW SYSTEM / 01</div><h2>What should your<br>system do?</h2><p>Describe the outcome. Start with a small workflow that you can test and inspect.</p><div class="step-indicator"><span class="active">01 Describe</span><span>→</span><span>02 Review plan</span><span>→</span><span>03 Configure graph</span></div><label for="new-title">SYSTEM NAME</label><input type="text" id="new-title" value="${esc(newTitle||'Evidence-led research assistant')}" maxlength="70"/><label for="new-prompt">YOUR BRIEF</label><textarea id="new-prompt" placeholder="Research a question, check every claim against sources, and return a concise recommendation.">${esc(newPrompt)}</textarea><div class="choice-row"><button data-template="research">Research & evidence</button><button data-template="support">Support answer review</button></div><div class="callout">Prototype planner: your brief is saved, then applied to a fixed research-and-review template. No LLM generates this plan.</div><div class="modal-actions"><span>One orchestrator. Explicit checks. Bounded loops.</span><button class="button primary" data-action="plan">Review plan ${icon('arrow')}</button></div>`);
  else modal(`<div class="section-eyebrow">NEW SYSTEM / 02</div><h2>A small, inspectable system.</h2><p>${esc(newTitle)}</p><div class="step-indicator"><span>01 Describe</span><span>→</span><span class="active">02 Review plan</span><span>→</span><span>03 Configure graph</span></div>${[['Protect the boundary','An input policy screens the request before any agent or tool runs.'],['Delegate the evidence work','The orchestrator hands one bounded task to a research agent with read-only knowledge access.'],['Review, then revise if needed','An evidence evaluator checks sources. Allow at most two revision cycles, then stop with an explanation.'],['Release a checked response','The orchestrator composes; the response policy validates schema and citation presence before release.']].map((s,i)=>`<div class="plan-step"><span>0${i+1}</span><div><h3>${s[0]}</h3><p>${s[1]}</p></div></div>`).join('')}<div class="callout">6 components · 9 typed connections · explicit input and output schemas. Your brief becomes the orchestrator’s goal. Existing runs keep their graph snapshots.</div><div class="modal-actions"><button class="button" data-action="back-plan">Edit brief</button><button class="button primary" data-action="create-system">Create graph ${icon('arrow')}</button></div>`);
}
function showSettings(){modal(`<div class="section-eyebrow">CONNECTIONS / RUNTIME</div><h2>Try the loop.<br>Keep it local.</h2><p>This prototype runs entirely in your browser. It uses sample outputs to demonstrate execution, guardrails and reflection.</p><div class="callout">Active: local fixture engine. No requests leave this app. API keys are not needed or collected.</div><label>LIVE PROVIDER · PLANNED</label><input type="text" value="Provider selection requires a connected backend" disabled/><label>API KEY · DISABLED IN THIS PROTOTYPE</label><input type="password" placeholder="Add through a secret store in the live product" disabled/><p>The real app should keep keys in a server-side secret store and pass scoped credentials to isolated workers. Keys must never enter exported graphs, prompts or traces.</p><div class="modal-actions"><span>Production runtime is not built yet.</span><button class="button primary" data-action="close-modal">Use demo fixtures</button></div>`);}
function showImport(preview=false){
  modal(`<div class="section-eyebrow">CODE DISCOVERY / PROPOSED SECOND MODE</div><h2>Your code. A clearer map.</h2><p>Import must start as read-only discovery. The source repository remains authoritative until you explicitly adopt a supported execution contract.</p><div class="import-comparison"><div><strong>Declared structure</strong><p>Parse supported framework definitions, schemas and source references. Dynamic dispatch may remain unresolved.</p><span class="mini-pill">STATIC / PARTIAL</span></div><div><strong>Observed execution</strong><p>Overlay instrumented runs to reveal actual calls, outputs and failures. A trace is evidence of one path, not all possible paths.</p><span class="mini-pill">TRACES / OBSERVED</span></div></div>${preview?`<div class="output-heading">ILLUSTRATIVE IMPORT PREVIEW · NOT CONNECTED TO A REPOSITORY</div><div class="mini-graph">support.py:18  orchestrator   [declared]\n  ├─ tools.py:42  search     [declared]\n  └─ review.py:9  validator  [observed in sample trace]\n     └─ dynamic_tool(...)   [unresolved]</div><div class="callout amber">Unknown edges stay unknown. Future edits should generate a source-linked patch with a diff, tests and explicit ownership—not silently rewrite arbitrary code.</div>`:`<label>REPOSITORY CONNECTION · PLANNED</label><input type="text" placeholder="Connect a supported repository in the live product" disabled/><p>Repository parsing, tracing adapters and source patching are not implemented in this mockup.</p>`}<div class="modal-actions"><span>Begin with one framework and a read-only adapter.</span><button class="button primary" data-action="${preview?'close-modal':'import-preview'}">${preview?'Back to workspace':'Preview example import'} ${icon('arrow')}</button></div>`,true);
}
function showLibrary(){modal(`<div class="section-eyebrow">COMPONENT LIBRARY</div><h2>Purpose, made explicit.</h2><p>Your original kingdom vocabulary lives alongside plain technical names. Select an existing component to inspect its contract.</p><div class="library-grid">${draft.nodes.map(n=>`<button class="library-item" data-library-node="${n.id}">${icon(n.icon)}<strong>${esc(n.name)}</strong><small>${esc(n.realm)} / ${esc(n.kind)}</small></button>`).join('')}</div><div class="callout">Future components: deterministic router, transform, parallel join, human approval and reusable subgraph. Each needs explicit runtime semantics before it enters the library.</div>`);}
function supportingFor(id){return draft.supportingNodes.filter(n=>n.dependsOn.includes(id));}
function showHiddenNodes(){modal(`<div class="section-eyebrow">FULL APPLICATION / SUPPORTING LAYER</div><h2>The rest of the app.<br>Out of the way, within reach.</h2><p>UI, database wiring, authentication and Markdown stay in the same application graph. They are collapsed by default so the workflow stays readable.</p><div class="support-list">${draft.supportingNodes.map(n=>`<button class="support-item" data-support-node="${n.id}"><span class="support-icon">${icon(n.icon)}</span><span><strong>${esc(n.name)}</strong><small>${esc(n.path)}</small></span><span>${n.dependsOn.length} DEPENDENC${n.dependsOn.length===1?'Y':'IES'}</span>${icon('chevron')}</button>`).join('')}</div><div class="callout">Hidden means visually collapsed. An authorization failure or database timeout must still surface on the affected workflow node and its trace. These source references are illustrative in this prototype.</div><div class="modal-actions"><span>4 supporting nodes · included in graph exports</span><button class="button" data-action="close-modal">Back to workflow</button></div>`,true);}
function renderSupportingContent(n){
  if(inspectorTab==='output'||inspectorTab==='activity')return `<div class="support-full"><div class="callout">${n.kind==='DOCS'?'Documentation is context, not an executable step. A real run would record the exact document version bound into its prompt.':'This supporting resource is not instrumented in the fixture simulation. A live runtime would link its events to the calling workflow invocation.'}</div><div class="output-heading">DEPENDENCIES</div>${n.dependsOn.map(id=>`<button class="support-dependency" data-node="${id}"><span>${esc(n.relationship)} ${esc(nodeName(id))}</span>${icon('arrow')}</button>`).join('')}</div>`;
  return `<div class="support-full"><div class="field"><label>Source reference · illustrative</label><div class="source-path">${esc(n.path)}</div></div><div class="field"><label for="support-description">Purpose</label><textarea id="support-description" class="code-editor short" ${running?'disabled':''}>${esc(n.prompt)}</textarea></div><div class="field"><div class="field-title"><label for="support-code">${n.kind==='DOCS'?'Markdown content':'Implementation code'}</label><span>${n.kind==='DOCS'?'MARKDOWN':'TYPESCRIPT'}</span></div><textarea id="support-code" class="code-editor support-code" spellcheck="false" ${running?'disabled':''}>${esc(n.code)}</textarea><p class="editor-hint">Edits are stored in this graph draft. No repository file is changed or executed.</p></div><div class="field"><label>Connected workflow nodes</label>${n.dependsOn.map(id=>`<button class="support-dependency" data-node="${id}"><span>${esc(n.relationship)} ${esc(nodeName(id))}</span>${icon('arrow')}</button>`).join('')}</div><div class="pill-row"><span class="mini-pill">Collapsed by default</span><span class="mini-pill">Versioned with graph</span></div></div>`;
}
function exportGraph(){const output={format:'citadel-prototype/v1',executable:false,description:'Prototype configuration. Prompts and code are illustrative; requires an implementation of the proposed runtime.',...clone(draft)};const blob=new Blob([JSON.stringify(output,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`citadel-graph-v${draft.version}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Graph exported. No credentials or run inputs included.');}
function validateGraph(){const issues=[];for(const e of draft.edges){if(!['input','output',...draft.nodes.map(n=>n.id)].includes(e.from)||!['input','output',...draft.nodes.map(n=>n.id)].includes(e.to))issues.push('Unknown node reference: '+e.id);if(e.type==='Feedback'&&(!Number.isInteger(e.maxAttempts)||e.maxAttempts<0||e.maxAttempts>3))issues.push('Invalid retry bound.');try{JSON.parse(e.mapping);}catch{issues.push('Invalid data binding.');}}toast(issues.length?issues.join(' '):'Structural checks passed: node references, JSON bindings and retry bounds. Code and schema compatibility are not executed.');}

document.addEventListener('click',event=>{
  const target=event.target.closest('button,[data-edge]');
  if(event.target.classList.contains('modal-backdrop')){closeModal();return;}if(!target)return;
  if(target.dataset.page){showPage(target.dataset.page);return;}
  if(target.dataset.node){selectItem(target.dataset.node);return;}
  if(target.dataset.edge){selectItem(target.dataset.edge,'edge');return;}
  if(target.dataset.view){view=target.dataset.view;$$('[data-view]').forEach(b=>b.classList.toggle('active',b===target));renderGraph();return;}
  if(target.dataset.inspectorTab){inspectorTab=target.dataset.inspectorTab;renderInspector();return;}
  if(target.dataset.attempt){outputAttempt=target.dataset.attempt;renderInspector();return;}
  if(target.dataset.runId){selectedRunId=target.dataset.runId;renderRuns();return;}
  if(target.dataset.traceInvocation){loadRun(target.dataset.traceRun,target.dataset.traceInvocation);return;}
  if(target.dataset.traceIndex!==undefined){replayToken++;replaying=false;scrubTrace(Number(target.dataset.traceIndex));return;}
  if(target.dataset.compareInspect){closeModal();loadRun(target.dataset.compareInspect);return;}
  if(target.dataset.libraryNode){closeModal();showPage('graph');selectItem(target.dataset.libraryNode);return;}
  if(target.dataset.supportNode){closeModal();showPage('graph');selectItem(target.dataset.supportNode);return;}
  if(target.dataset.template){$('#new-prompt').value=target.dataset.template==='support'?'Draft a support answer using approved documentation. Check claims and citations. Revise up to two times, then escalate if evidence remains insufficient.':'Research a question, compare options with evidence, and return a concise recommendation. Check every claim against sources before releasing the answer.';return;}
  switch(target.dataset.action){
    case 'run':runSystem();break;
    case 'apply':applyChanges();break;
    case 'fit':fitGraph();toast('Graph fitted to workspace.');break;
    case 'validate':validateGraph();break;
    case 'export':exportGraph();break;
    case 'new':newSystem();break;
    case 'plan':newPrompt=$('#new-prompt').value.trim();newTitle=$('#new-title').value.trim();if(!newPrompt||!newTitle){toast('Add a system name and a brief first.');break;}newPlanStep=2;renderNewSystem();break;
    case 'back-plan':newPlanStep=1;renderNewSystem();break;
    case 'create-system':replayToken++;replaying=false;traceCursor=null;debugMission=null;draft=clone(defaults);draft.title=newTitle;draft.goal=newPrompt;draft.nodes.find(n=>n.id==='king').prompt+='\n\nSystem goal: '+newPrompt;saveDraft();currentRun=null;selected='research';selectedType='node';inspectorTab='configuration';closeModal();showPage('graph');$('#response-content').className='response-placeholder';$('#response-content').innerHTML=`${icon('spark')}<p>Your graph is ready.</p><span>Edit any component, then run a fixture.</span>`;$('#response-badge').textContent='Waiting for run';$('#playground-status').textContent='Ready when you are';renderGraph();renderInspector();renderTraceStrip();toast('Created a new template-based graph. Earlier runs remain in Runs.');break;
    case 'settings':showSettings();break;
    case 'import':showImport();break;
    case 'import-preview':showImport(true);break;
    case 'library':showLibrary();break;
    case 'hidden-nodes':showHiddenNodes();break;
    case 'search':showSearch();break;
    case 'compare':compareRuns();break;
    case 'replay':replayTrace();break;
    case 'trace-end':replayToken++;replaying=false;traceCursor=null;renderGraph();renderTraceStrip();break;
    case 'debug-tour':startDebugMission();break;
    case 'begin-debug':closeModal();draft.edges.find(e=>e.id==='e5').maxAttempts=0;draft.nodes.find(n=>n.id==='council').threshold=0.85;draft.version++;saveDraft();$('#scenario').value='repair';$('#sample-input').value=samples.repair;debugMission={stage:'failure'};runSystem();break;
    case 'inspect-fix':closeModal();showPage('graph');selectItem('e5','edge');$('#edge-attempts').value=1;$('#edge-attempts').focus();toast('Suggested repair: 1 revision. Apply changes, then run again.');break;
    case 'close-modal':closeModal();break;
    case 'view-run':loadRun(selectedRunId||history[0]?.id);break;
    case 'about':showPage('blueprint');break;
  }
});
document.addEventListener('keydown',event=>{
  if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();showSearch();}
  if(event.key==='Escape')closeModal();
  if((event.key==='Enter'||event.key===' ')&&event.target.matches('[data-edge]')){event.preventDefault();selectItem(event.target.dataset.edge,'edge');}
  if(event.key==='Tab'&&$('.modal')){const focusable=$$('button:not(:disabled),input:not(:disabled),textarea,select,a[href]', $('.modal'));const first=focusable[0],last=focusable.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}
});
document.addEventListener('input',event=>{if(event.target.id==='command-search')renderSearch(event.target.value);});
$('#scenario').addEventListener('change',event=>{$('#sample-input').value=samples[event.target.value];});
new ResizeObserver(fitGraph).observe($('#graph-canvas'));
paintIcons();renderHeader();renderGraph();renderInspector();fitGraph();
$('#response-content').insertAdjacentHTML('beforeend','<button class="guided-button" data-action="debug-tour">Try a guided failure & repair '+icon('arrow')+'</button>');
